// eventMsgPayload is the payload for type="event_msg" lines.
type eventMsgPayload struct {
	Type   string          `json:"type"` // "token_count", "task_started", "user_message", "agent_message", "task_complete"
	TurnID *string         `json:"turn_id,omitempty"`
	Info   json.RawMessage `json:"info,omitempty"`
	Item   json.RawMessage `json:"item,omitempty"`
}

type fileChangeItem struct {
	Type    string                     `json:"type"`
	Status  string                     `json:"status"`
	Changes map[string]json.RawMessage `json:"changes"`
}

// tokenCountInfo contains token usage data from event_msg.token_count.
type tokenCountInfo struct {
	TotalTokenUsage *tokenUsageData `json:"total_token_usage,omitempty"`
}

// tokenUsageData maps to Codex's token usage fields.
type tokenUsageData struct {
	InputTokens           int `json:"input_tokens"`
	CachedInputTokens     int `json:"cached_input_tokens"`
	if lastUsage == nil {
		return nil, nil //nolint:nilnil // no usage data found
	}

	// Subtract baseline to get the delta for this checkpoint range
	inputTokens := lastUsage.InputTokens
	cacheReadTokens := lastUsage.CachedInputTokens
	outputTokens := lastUsage.OutputTokens
	if baselineUsage != nil {
		inputTokens -= baselineUsage.InputTokens
		cacheReadTokens -= baselineUsage.CachedInputTokens
		outputTokens -= baselineUsage.OutputTokens
	}

	freshInputTokens := inputTokens - cacheReadTokens
	if freshInputTokens < 0 {
		freshInputTokens = 0
	}

	return &agent.TokenUsage{
		InputTokens:     freshInputTokens,
		CacheReadTokens: cacheReadTokens,
		OutputTokens:    outputTokens,
		APICallCount:    apiCalls,
	}, nil
}

type rolloutAnalysis struct {
	ModifiedFiles   []string
	TerminalTurnIDs []string
	ExactTokenUsage *agent.TokenUsage
}

// analyzeRollout extracts every piece of child evidence in one JSONL pass.
// Each evidence channel keeps its own validity: malformed task boundaries
// invalidate terminal turns without discarding file paths already observed,
// while a malformed final token snapshot makes exact usage unavailable.
func analyzeRollout(data []byte, fromOffset int) rolloutAnalysis {
	var result rolloutAnalysis
	terminalValid := true
	scopeValid := true
	openTurn := ""
	seenTurns := make(map[string]struct{})
	seenFiles := make(map[string]struct{})
	var lastTokenInfo json.RawMessage
	foundToken := false
	lines := splitJSONL(data)
	var localStartOrdinal *int
	if len(lines) > 0 {
		var first rolloutLine
		if json.Unmarshal(lines[0], &first) == nil && first.Type == rolloutLineTypeSessionMeta {
			var meta sessionMetaPayload
			if json.Unmarshal(first.Payload, &meta) == nil && meta.SubagentHistoryStartOrdinal != nil && *meta.SubagentHistoryStartOrdinal >= 0 {
				localStartOrdinal = meta.SubagentHistoryStartOrdinal
			}
		}
	}

	for index, lineData := range lines {
		var line rolloutLine
		if json.Unmarshal(lineData, &line) != nil {
			terminalValid = false
			if localStartOrdinal != nil {
				scopeValid = false
			}
			continue
		}
		if localStartOrdinal != nil {
			if line.Ordinal == nil {
				scopeValid = false
				continue
			}
			if *line.Ordinal < *localStartOrdinal {
				continue
			}
		}
		if index+1 > fromOffset {
			for _, file := range extractFilesFromParsedLine(line) {
				if _, seen := seenFiles[file]; !seen {
					seenFiles[file] = struct{}{}
					result.ModifiedFiles = append(result.ModifiedFiles, file)
				}
			}
		}
		if line.Type != rolloutLineTypeEventMsg {
			continue
		}

		var header struct {
			Type string `json:"type"`
		}
		if json.Unmarshal(line.Payload, &header) != nil {
			terminalValid = false
			continue
		}
		if header.Type != eventMsgTypeTokenCount && header.Type != "task_started" && header.Type != "task_complete" {
			continue
		}
		var event eventMsgPayload
		if json.Unmarshal(line.Payload, &event) != nil {
			if header.Type != eventMsgTypeTokenCount {
				terminalValid = false
			}
			continue
		}
		switch header.Type {
		case eventMsgTypeTokenCount:
			foundToken = true
			lastTokenInfo = event.Info
		case "task_started":
			if openTurn != "" || event.TurnID == nil || *event.TurnID == "" {
				terminalValid = false
				continue
			}
			if _, duplicate := seenTurns[*event.TurnID]; duplicate {
				terminalValid = false
				continue
			}
			openTurn = *event.TurnID
		case "task_complete":
			if openTurn == "" || (event.TurnID != nil && (*event.TurnID == "" || *event.TurnID != openTurn)) {
				terminalValid = false
				continue
			}
			result.TerminalTurnIDs = append(result.TerminalTurnIDs, openTurn)
			seenTurns[openTurn] = struct{}{}
			openTurn = ""
		}
	}
	if !scopeValid {
		return rolloutAnalysis{}
	}
	if !terminalValid || openTurn != "" {
		result.TerminalTurnIDs = nil
	}
	if foundToken {
		result.ExactTokenUsage = exactUsageFromInfo(lastTokenInfo)
	}
	return result
}

func extractFilesFromParsedLine(line rolloutLine) []string {
	switch line.Type {
	case rolloutLineTypeResponseItem:
		var payload responseItemPayload
		if json.Unmarshal(line.Payload, &payload) != nil || payload.Type != "custom_tool_call" || payload.Name != "apply_patch" {
			return nil
		}
		return extractFilesFromApplyPatch(payload.Input)
	case rolloutLineTypeEventMsg:
		var event eventMsgPayload
		if json.Unmarshal(line.Payload, &event) != nil || event.Type != "item_completed" {
			return nil
		}
		var item fileChangeItem
		if json.Unmarshal(event.Item, &item) != nil || item.Type != "FileChange" || item.Status != "completed" {
			return nil
		}
		files := make([]string, 0, len(item.Changes))
		for path := range item.Changes {
			if path != "" {
				files = append(files, path)
			}
		}
		sort.Strings(files)
		return files
	default:
		return nil
	}
}

func exactUsageFromInfo(lastInfo json.RawMessage) *agent.TokenUsage {
	if len(lastInfo) == 0 {
		return nil
	}
	var info struct {
		TotalTokenUsage *exactTokenUsageData `json:"total_token_usage"`
	}
	if json.Unmarshal(lastInfo, &info) != nil || info.TotalTokenUsage == nil {
		return nil
	}
	usage := info.TotalTokenUsage
	if usage.InputTokens == nil || usage.CachedInputTokens == nil || usage.OutputTokens == nil {
		return nil
	}
	input, cached, output := *usage.InputTokens, *usage.CachedInputTokens, *usage.OutputTokens
	if input < 0 || cached < 0 || output < 0 || cached > input {
		return nil
	}
	if usage.ReasoningOutputTokens != nil && (*usage.ReasoningOutputTokens < 0 || *usage.ReasoningOutputTokens > output) {
		return nil
	}
	if usage.TotalTokens != nil && (*usage.TotalTokens < 0 || *usage.TotalTokens != input+output) {
		return nil
	}
	return &agent.TokenUsage{InputTokens: input - cached, CacheReadTokens: cached, OutputTokens: output}
}

// ExtractWithSubagentInventory gathers evidence only for refs supplied by the
// caller's authoritative ledger. It never discovers children from transcript
// text, filenames, timestamps, or token-count events.
func (c *CodexAgent) ExtractWithSubagentInventory(ctx context.Context, parent []byte, fromOffset int, refs []agent.SubagentReference) (agent.InventoryExtraction, error) {
	result := agent.InventoryExtraction{ModifiedFiles: analyzeRollout(parent, fromOffset).ModifiedFiles}
	parentUsage, err := c.CalculateTokenUsage(parent, fromOffset)
	if err != nil {
		return result, err
	}
	complete := true
	var childTotal *agent.TokenUsage
	resolved := make([]loadedRollout, len(refs))
	unresolvedIDs := make(map[string]struct{})
	for index, ref := range refs {
		if loaded, ok := c.loadDirectRollout(ctx, ref); ok {
			resolved[index] = loaded
		} else if ref.AgentID != "" {
			unresolvedIDs[ref.AgentID] = struct{}{}
		}
	}
	fallback, fallbackErr := c.scanFallbackRollouts(ctx, unresolvedIDs)
	if fallbackErr != nil {
		fallback = nil
	}
	for index, ref := range refs {
		if resolved[index].Path == "" {
			resolved[index] = fallback[ref.AgentID]
		}
	}
	for index, ref := range refs {
		analysis := agent.SubagentAnalysis{AgentID: ref.AgentID}
		loaded := resolved[index]
		analysis.ResolvedPath = loaded.Path
		if loaded.Path == "" {
			complete = false
			result.Children = append(result.Children, analysis)
			continue
		}
		rollout := analyzeRollout(loaded.Data, 0)
		analysis.ModifiedFiles = rollout.ModifiedFiles
		analysis.TerminalTurnIDs = rollout.TerminalTurnIDs
		analysis.TokenUsage = rollout.ExactTokenUsage
		if analysis.TokenUsage == nil {
			complete = false
		} else {
			childTotal = addExactUsage(childTotal, analysis.TokenUsage)
		}
		result.ModifiedFiles = appendUniqueFiles(result.ModifiedFiles, analysis.ModifiedFiles)
		result.Children = append(result.Children, analysis)
	}
	result.TokenUsage = withChildCoverage(parentUsage, complete)
	if complete && len(refs) > 0 {
		result.TokenUsage.SubagentTokens = childTotal
	}
	return result, nil
}

func withChildCoverage(usage *agent.TokenUsage, complete bool) *agent.TokenUsage {
	if usage == nil {
		return &agent.TokenUsage{SubagentTokensComplete: &complete}
	}
	result := *usage
	result.SubagentTokens = nil
	result.SubagentTokensComplete = &complete
	return &result
}

func appendUniqueFiles(files, additions []string) []string {
	seen := make(map[string]struct{}, len(files)+len(additions))
	for _, file := range files {
		seen[file] = struct{}{}
	}
	for _, file := range additions {
		if _, exists := seen[file]; !exists {
			seen[file] = struct{}{}
			files = append(files, file)
		}
	}
	return files
}

func addExactUsage(total, addition *agent.TokenUsage) *agent.TokenUsage {
	if total == nil {
		cloned := *addition
		return &cloned
	}
	total.InputTokens += addition.InputTokens
	total.CacheReadTokens += addition.CacheReadTokens
	total.OutputTokens += addition.OutputTokens
	return total
}

// ExtractPrompts returns user prompts from the transcript starting at the given offset.
func (c *CodexAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}

	var prompts []string
	lineNum := 0

	for _, lineData := range splitJSONL(data) {
		lineNum++
		if lineNum <= fromOffset {
			continue
		}

		var line rolloutLine
		if json.Unmarshal(lineData, &line) != nil {
			continue
		}

		if line.Type != rolloutLineTypeResponseItem {
			continue
		}

		var payload responseItemPayload
		if json.Unmarshal(line.Payload, &payload) != nil {
			continue
		}

		if payload.Type != "message" || payload.Role != "user" {
			continue
		}

		// Extract text from content items
		var items []contentItem
		if json.Unmarshal(payload.Content, &items) != nil {
			continue
		}
		for _, item := range items {
			text := strings.TrimSpace(item.Text)
			if text != "" && item.Type == "input_text" {
				prompts = append(prompts, text)
			}
		}
	}

	return prompts, nil
}

// SanitizePortableTranscript strips encrypted history fragments that cannot be
// replayed when Entire reconstructs a Codex rollout outside its original
// session context.
func SanitizePortableTranscript(data []byte) []byte {
	if !mayNeedSanitizing(data) {
		return data
	}

	lines := splitJSONL(data)
	if len(lines) == 0 {
		return data
	}

	sanitized := make([][]byte, 0, len(lines))
	changed := false
	for _, lineData := range lines {
		updated, keep := sanitizeRolloutLine(lineData)
		if !keep {
			changed = true
			continue
		}
		if !bytes.Equal(updated, lineData) {
			changed = true
		}
		sanitized = append(sanitized, updated)
	}

	// Nothing to strip: hand back the original bytes rather than paying the
	// reassembly copy. Callers rely on this being cheap — sanitization is
	// idempotent precisely so every storage path can call it without tracking
	// whether an upstream path already did.
	if !changed {
		return data
	}
	if len(sanitized) == 0 {
		return data
	}
	return agent.ReassembleJSONL(sanitized)
}

// sanitizeMarkers are the substrings that gate every transformation
// sanitizeRolloutLine performs: dropping "compaction"/"compaction_summary" items,
// rewriting "compacted" lines, and deleting "encrypted_content" from "reasoning"
// items. A transcript containing none of them cannot be altered, so one scan lets
// us skip unmarshalling every line.
//
// Deliberately over-broad ("compact" covers compacted/compaction/
// compaction_summary): a false positive just falls through to the full pass, while
// a false negative would silently skip sanitization.
var sanitizeMarkers = [][]byte{
	[]byte("encrypted_content"),
	[]byte("compact"),
	[]byte("reasoning"),
}

func mayNeedSanitizing(data []byte) bool {
	for _, marker := range sanitizeMarkers {
		if bytes.Contains(data, marker) {
	var appendedSkillEvents []agent.SkillEvent
	mutErr := strategy.MutateSessionStateOnSaved(ctx, event.SessionID, func(state *strategy.SessionState) error {
		appendedSkillEvents = persistEventMetadataToState(event, state)
		if transErr := strategy.TransitionAndLog(ctx, state, session.EventCompaction, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
			logging.Warn(logCtx, "compaction transition failed",
				slog.String("error", transErr.Error()))
		}
		return nil
	}, func() {
		strategy.EmitSkillInvocationTelemetry(ctx, appendedSkillEvents)
	})
	if mutErr != nil && !errors.Is(mutErr, strategy.ErrStateNotFound) {
		logging.Warn(logCtx, "failed to save session state after compaction",
			slog.String("error", mutErr.Error()))
	}

	logging.Info(logCtx, "context compaction detected")
	return nil
}

// handleLifecycleSessionEnd handles session end: marks the session as ended.
func handleLifecycleSessionEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
	logging.Info(logCtx, "session-end",
		slog.String("event", event.Type.String()),
		slog.String("session_id", event.SessionID),
	)

	if event.SessionID == "" {
		return nil // No session to update
	}

	// Note: We intentionally don't clean up cached transcripts here.
	// Post-session commits (carry-forward in ENDED phase) may still need
	// the transcript to extract file changes. Cleanup is handled by
	// `entire clean` or when the session state is fully removed.

	// Finalize any background subagent still in flight BEFORE endSessionNow:
	// endSessionNow marks the session ended and immediately runs the eager
	// condense, which materializes whatever records are completed by then.
	// Completing after it would leave records nothing then condenses — the
	// zombie class handleSubagentStopFinal's late-arrival guard exists to
	// prevent. See completeLiveTaskRecords.
	// NOTE: this runs ahead of the session-end condense deadline
	// (sessionEndCondenseDeadline) that budget-capped agents get; Claude Code
	// sets no budget, and for agents that do, bounding the final captures
	// against the same deadline is a known follow-up.
	if ag.Type() == agent.AgentTypeCodex {
		if transcript, readErr := ag.ReadTranscript(event.SessionRef); readErr == nil {
			_, _ = refreshCodexInventory(ctx, ag, event.SessionID, transcript, 0)
		}
		finalizeCodexObservedAtSessionEnd(ctx, event.SessionID)
	}
	completeLiveTaskRecords(ctx, ag, event.SessionID, event.SessionRef)

	if _, err := endSessionNow(ctx, event, event.SessionID, nil, sessionEndCondenseDeadline(ag), endedNow); err != nil {
		logging.Warn(logCtx, "failed to mark session ended",
			slog.String("error", err.Error()))
	}

	return nil
}

// finalizeCodexObservedAtSessionEnd closes every observed turn that did not
// have a matching terminal record in the same verified rollout analysis. This
// deliberately iterates the inventory rather than live task records: a
// follow-up can be hidden behind a completed-but-unmaterialized record.
func finalizeCodexObservedAtSessionEnd(ctx context.Context, sessionID string) {
	if err := strategy.MutateSessionState(ctx, sessionID, func(state *strategy.SessionState) error {
		for _, entry := range state.SubagentInventory {
			for _, turnID := range entry.ObservedTurnIDs {
				if !state.FinalizeSubagentTurn(entry.AgentID, turnID) {
					continue
				}
				for i := range state.TaskRecords {
					record := &state.TaskRecords[i]
					if record.AgentID != entry.AgentID {
						continue
					}
					if record.CompletedAt.IsZero() {
						record.CompletedAt = time.Now()
					}
					// refreshCodexInventory accepts this path only after loading the
					// rollout and matching session_meta.id to AgentID. Carry that
					// verified path into the durable task record even when this
					// fallback has no exact terminal file/token snapshot.
					if entry.ResolvedTranscriptPath != "" {
						record.DeclaredTranscriptPath = entry.ResolvedTranscriptPath
					}
					record.Files = nil
					record.TokenUsage = nil
					break
				}
			}
		}
		return nil
	}); err != nil && !errors.Is(err, strategy.ErrStateNotFound) {
		logging.Debug(ctx, "failed to finalize codex turns at session end", slog.String("error", err.Error()))
	}
}

// refreshCodexInventory snapshots the durable child ledger, performs the
// potentially slow filesystem analysis outside its lock, then applies only
// path enrichment and terminal evidence if no new child observation raced it.
// It never manufactures an exact-empty result for an unknown/legacy ledger.
func refreshCodexInventory(ctx context.Context, ag agent.Agent, sessionID string, parent []byte, fromOffset int) (*agent.TokenUsage, *uint64) {
	state, err := strategy.LoadSessionState(ctx, sessionID)
	if err != nil || state == nil || state.SubagentInventoryComplete == nil {
		return nil, nil
	}
	refs := make([]agent.SubagentReference, 0, len(state.SubagentInventory))
	for _, entry := range state.SubagentInventory {
		refs = append(refs, agent.SubagentReference{AgentID: entry.AgentID, DeclaredTranscriptPath: entry.DeclaredTranscriptPath, ResolvedTranscriptPath: entry.ResolvedTranscriptPath})
	}
	version := state.SubagentLedgerVersion
	extraction, ok := agent.ExtractWithSubagentInventory(ctx, ag, parent, fromOffset, refs)
	if !ok {
		return nil, &version
	}

	usage := extraction.TokenUsage
	if err := strategy.MutateSessionState(ctx, sessionID, func(current *strategy.SessionState) error {
		if current.SubagentLedgerVersion != version {
			return strategy.ErrMutationSkip
		}
		usage = extraction.TokenUsage
		if current.SubagentInventoryComplete == nil || !*current.SubagentInventoryComplete {
			// A legacy/partial inventory may still provide main transcript evidence,
			// but cannot truthfully claim full child coverage.
			usage = types.WithClearedSubagentTokens(usage, false)
		}
		for _, child := range extraction.Children {
			childFiles := FilterAndNormalizePaths(child.ModifiedFiles, current.WorktreePath)
			current.UpdateSubagentTranscriptPaths(child.AgentID, "", child.ResolvedPath)
			for _, turnID := range child.TerminalTurnIDs {
				if !current.FinalizeSubagentTurn(child.AgentID, turnID) {
					continue
				}
				for i := range current.TaskRecords {
					record := &current.TaskRecords[i]
					if record.AgentID != child.AgentID {
						continue
					}
					if record.CompletedAt.IsZero() {
						record.CompletedAt = time.Now()
					}
					record.Files = childFiles
					record.DeclaredTranscriptPath = child.ResolvedPath
					// nil is evidence too: a newer terminal snapshot without exact
					// usage must clear, never preserve, an earlier total.
					record.TokenUsage = child.TokenUsage
					current.FilesTouched = mergeUnique(current.FilesTouched, childFiles)
					break
				}
			}
		}
		// This is also the no-file refresh path: retain the latest exact child
		// snapshot (including authoritative empty or unavailable) without
		// creating a checkpoint step or changing main-agent counters.
		if usage != nil {
			if current.TokenUsage == nil {
				current.TokenUsage = &agent.TokenUsage{}
			}
			current.TokenUsage.SubagentTokens = usage.SubagentTokens
			if usage.SubagentTokensComplete != nil {
				complete := *usage.SubagentTokensComplete
				current.TokenUsage.SubagentTokensComplete = &complete
			}
		}
		return nil
	}); err != nil && !errors.Is(err, strategy.ErrStateNotFound) {
		logging.Debug(ctx, "failed to persist codex inventory evidence", slog.String("error", err.Error()))
	}
	return usage, &version
}

// processStart approximates when this hook process began. Package
// initialization runs before main, so it is within milliseconds of exec —
// precise enough to bound work against a deadline the agent measures from the
// moment it spawned us.
var processStart = time.Now()
// declaredSubagentTranscript returns the agent-declared subagent transcript path
// when it names a file that exists, else "".
//
// A declared-but-missing path warns rather than falling through silently: it means
// the agent's contract and its behaviour disagree.
func declaredSubagentTranscript(ctx context.Context, event *agent.Event) string {
	declared := strings.TrimSpace(event.SubagentTranscriptPath)
	if declared == "" {
		return ""
	}
	if !fileExists(declared) {
		logging.Warn(ctx, "agent declared a subagent transcript that does not exist",
			slog.String("path", declared),
			slog.String("agent_id", event.SubagentID))
		return ""
	}
	return declared
}

// handleLifecycleSubagentEnd handles subagent completion. It dispatches on
// event.Final — never on any payload sentinel — to tell a real completion
// signal (SubagentStop) from the launch-time PostToolUse (post-task) stub:
//
//   - event.Final == true (SubagentStop): the authoritative final capture.
//     See handleSubagentStopFinal.
//   - event.Final == false, background launch (run_in_background: true in
//     ToolInput): post-task fires seconds after launch, before any real work
//     happens. Records an in-flight marker and defers the real capture to
//     SubagentStop instead of completing the record from the stub.
//   - event.Final == false, foreground: post-task fires at true completion, so
//     the record is completed immediately via completeSubagentTaskRecord.
//     ensureSessionState preserves SaveTaskStep's old create-if-missing parent
//     state guarantee for this path (the Final path deliberately never
//     resurrects state — see handleSubagentStopFinal's zombie guard).
func handleLifecycleSubagentEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
	if event.SubagentType == "" && event.TaskDescription == "" {
		// Extract subagent type and description from tool input
		event.SubagentType, event.TaskDescription = ParseSubagentTypeAndDescription(event.ToolInput)
	}
	if ag.Type() == agent.AgentTypeCodex && event.ProvisionalSubagentStop {
		if event.SubagentID == "" || event.TurnID == "" {
			return errors.New("invalid codex provisional subagent stop: agent and turn IDs are required")
		}
		// Codex's stop hook is deliberately not completion: its rollout can
		// still be changing. Record only the observation for later transcript
		// reconciliation; do not capture the parent worktree or mark a task done.
		err := strategy.MutateSessionState(logCtx, event.SessionID, func(state *strategy.SessionState) error {
			state.RecordSubagentStop(event.SubagentID, event.TurnID)
			state.UpdateSubagentTranscriptPaths(event.SubagentID, event.SubagentTranscriptPath, "")
			return nil
		})
		if errors.Is(err, strategy.ErrStateNotFound) {
			return nil
		}
		if err != nil {
			return fmt.Errorf("record codex provisional subagent stop: %w", err)
		}
		return nil
	}

	if event.Final {
		return handleSubagentStopFinal(logCtx, ag, event)
	}

	if isBackgroundLaunch(logCtx, event.ToolInput) {
		return recordInFlightTaskLaunch(logCtx, event)
	}

	return completeSubagentTaskRecord(logCtx, ag, event, subagentCaptureOptions{ensureSessionState: true})
}

// recordInFlightTaskLaunch handles a background Task launch. It records an
// in-flight marker on session state and completes nothing yet;
// the real capture happens at SubagentStop (handleSubagentStopFinal), which
// is the first point that sees the subagent's actual work. Tolerates
// strategy.ErrStateNotFound the way the completion producers tolerate a launch
// event arriving before session state exists.
func recordInFlightTaskLaunch(logCtx context.Context, event *agent.Event) error {
	logging.Debug(logCtx, "background subagent launch detected; deferring capture to subagent-stop",
		slog.String("session_id", event.SessionID),
		slog.String("tool_use_id", event.ToolUseID),
		slog.String("agent_id", event.SubagentID),
	)

	mutErr := strategy.MutateSessionState(logCtx, event.SessionID, func(state *strategy.SessionState) error {
		state.AddTaskRecord(session.TaskRecord{
			ToolUseID:       event.ToolUseID,
			AgentID:         event.SubagentID,
			StartedAt:       time.Now(),
			SubagentType:    event.SubagentType,
		s.CondensationAttempt.RecoveryPending = true
	}
}

// NeedsCondensationRecovery reports whether doctor must reconcile a checkpoint
// written before attempt IDs existed.
func (s *State) NeedsCondensationRecovery() bool {
	return s.CondensationAttempt != nil && s.CondensationAttempt.RecoveryPending
}

// ClearCondensationAttempt completes or abandons the pending condensation.
func (s *State) ClearCondensationAttempt() {
	s.CondensationAttempt = nil
}

// RebaselineSubagentTokens snapshots the current cumulative subagent total
// (TokenUsage.SubagentTokens) into SubagentTokensBaseline so the next checkpoint
// window's CheckpointTokenUsage.SubagentTokens is rescoped to "since this
// re-baseline" rather than re-reporting the full cumulative subagent total.
//
// The invariant is: every site that starts a fresh checkpoint window by clearing
// CheckpointTokenUsage MUST also re-baseline. Callers: the condensation reset
// helper (resetCheckpointWindow) and cross-repo session adoption, which likewise
// opens a fresh target-local window. Sharing this here keeps the two in step.
func (s *State) RebaselineSubagentTokens() {
	if s.TokenUsage == nil || (s.TokenUsage.SubagentTokensComplete != nil && !*s.TokenUsage.SubagentTokensComplete) {
		incomplete := false
		s.SubagentTokensBaseline = nil
		s.SubagentTokensBaselineComplete = &incomplete
		return
	}
	// A nil marker retains the historic behaviour: the implicit initial
	// baseline is exact zero. An explicit complete marker can intentionally
	// snapshot a nil aggregate for an authoritative empty inventory.
	complete := true
	s.SubagentTokensBaseline = s.TokenUsage.SubagentTokens
	s.SubagentTokensBaselineComplete = &complete
}

// RealignAttributionBase sets AttributionBaseCommit to newBase and clears any
// bookkeeping whose meaning depends on attribution being diverged from the
// shadow-branch base. Call this every time a code path intentionally brings
// AttributionBaseCommit back in line with BaseCommit (condensation, reconcile,
// post-commit base advance) so a stale DivergenceNoticeShown cannot suppress
// the next legitimate divergence warning.
func (s *State) RealignAttributionBase(newBase string) {
	s.AttributionBaseCommit = newBase
	s.DivergenceNoticeShown = false
}

// IsStale returns true when a session hasn't seen interaction for longer than
// StaleSessionThreshold. Falls back to StartedAt when LastInteractionTime is
// nil (sessions created before interaction tracking was added).
// IsStuckActive returns true if the session is in ACTIVE phase but has not had
// any interaction for longer than StuckActiveThreshold. Falls back to StartedAt
// when LastInteractionTime is nil, so brand-new sessions are not falsely flagged.
"}

